import React from 'react';
import { Link } from 'react-router-dom';
import { FaMapMarkerAlt, FaCalendarCheck, FaPhoneAlt, FaHeadset } from 'react-icons/fa';

const MembershipBar = () => {
  return (
    <section className="membership-bar">
      <style>
        {`
          @media (max-width: 500px) {
            .membership-content {
              padding: 25px 15px !important;
              border-radius: 16px !important;
            }
            .membership-content h2 {
              font-size: 20px !important;
            }
            .perk-item p {
              font-size: 13px !important;
            }
            .membership-bar {
              margin-bottom: 1.5rem !important;
            }
          }
        `}
      </style>
      <div className="container container-two">

        <div 
          className="membership-content"
          style={{ 
            background: '#121435', 
            borderRadius: '24px',
            color: '#fff',
            padding: '45px 35px',
            boxShadow: '0 15px 40px rgba(0,0,0,0.2)'
          }}
        >
          <div className="text-center mb-4 pb-2">
            <h2 className="mb-0" style={{ fontSize: '28px', fontWeight: '800', color: '#fff' }}>
              Smarter Healthcare, Near You
            </h2>
          </div>

          <div className="d-flex flex-column align-items-center gap-4">
            {/* Perks Section */}
            <div className="d-flex align-items-center gap-xl-5 gap-4 flex-wrap justify-content-center">
              <div className="perk-item d-flex align-items-center gap-2">
                <FaMapMarkerAlt style={{ color: '#f59e0b', fontSize: '20px' }} />
                <div>
                  <p className="mb-0" style={{ fontSize: '14px', fontWeight: '700', color: '#fff' }}>Verified Labs</p>
                </div>
              </div>

              <div className="perk-item d-flex align-items-center gap-2">
                <FaCalendarCheck style={{ color: '#f59e0b', fontSize: '20px' }} />
                <div>
                  <p className="mb-0" style={{ fontSize: '14px', fontWeight: '700', color: '#fff' }}>Quick Booking</p>
                </div>
              </div>

              <div className="perk-item d-flex align-items-center gap-2">
                <FaPhoneAlt style={{ color: '#f59e0b', fontSize: '20px' }} />
                <div>
                  <p className="mb-0" style={{ fontSize: '14px', fontWeight: '700', color: '#fff' }}>Doctor on Call</p>
                </div>
              </div>

              <div className="perk-item d-flex align-items-center gap-2">
                <FaHeadset style={{ color: '#f59e0b', fontSize: '20px' }} />
                <div>
                  <p className="mb-0" style={{ fontSize: '14px', fontWeight: '700', color: '#fff' }}>24/7 Support</p>
                </div>
              </div>
            </div>

            {/* Action Section */}
            <div className="flex-shrink-0 mt-2">
              <Link 
                to="/all-service" 
                className="btn px-5" 
                style={{ 
                  border: '1px solid #f59e0b', 
                  color: '#fff', 
                  borderRadius: '12px',
                  fontWeight: '700',
                  paddingTop: '10px',
                  paddingBottom: '10px'
                }}
              >
                Explore
              </Link>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default MembershipBar;
